#include <stdio.h>
#include <stdlib.h>

typedef struct T { int v; struct T *l, *r; } T;
static T *ins(T *n, int v) {
    if (!n) { T *x = malloc(sizeof(T)); x->v = v; x->l = x->r = NULL; return x; }
    if (v < n->v)      n->l = ins(n->l, v);
    else if (v > n->v) n->r = ins(n->r, v);
    /* v == n->v 时忽略（约定：不存重复键） */
    return n;
}
static int find(T *n, int v, int *steps) {
    *steps = 0;
    while (n) {
        (*steps)++;
        if (v == n->v) return 1;
        n = (v < n->v) ? n->l : n->r;
    }
    return 0;
}
int main(void) {
    int vals[] = {50, 30, 70, 20, 40, 60, 80};
    T *root = NULL;
    for (int i = 0; i < 7; i++) root = ins(root, vals[i]);
    int steps, f1, f2;
    /* 注意：不能把 find(...) 与 steps 写在同一个 printf 的参数里 ——
       C 未规定参数求值顺序，steps 可能在 find 之前被读取，得到上一次/未初始化的值。 */
    f1 = find(root, 40, &steps);
    printf("查找 40: %s（比较 %d 次）\n", f1 ? "找到" : "未找到", steps);
    f2 = find(root, 45, &steps);
    printf("查找 45: %s（比较 %d 次）\n", f2 ? "找到" : "未找到", steps);
    return 0;
}
